-- KAI pgAdmin production migration packet: RP rollback precheck
-- READ-ONLY. One SELECT statement; it changes nothing and inserts nothing.
-- Run before any rollback file. Reports counts only (no row contents) and whether each rollback is safe.
-- A rollback is never needed after a migration whose verifier PASSED unless the application rollout is
-- abandoned. Roll back in reverse order (R04, R03, R02, R01), only for migrations actually applied.
-- Generated by scripts/kai-sprint2-pgadmin-production-packet-build.js from
--   artifacts/kai-db-reconciliation-2026-09-16/PRODUCTION_KAI_SCHEMA.json (owner pgAdmin capture, 2026-09-16) and
--   KAI_PGADMIN_PRODUCTION_MIGRATION_PACKET/support/expected_post_migration_catalog_pg16.json.
-- Run it in the pgAdmin Query Tool (Execute script, F5). Read the Data Output grid.
WITH
checks(seq, section, check_id, status, expected, observed, detail) AS (
  SELECT 101, 'RP', 'R04',
              CASE WHEN coalesce(s.n, 0) + coalesce(d.n, 0) = 0 THEN 'SAFE_TO_ROLL_BACK' ELSE 'UNSAFE_ROLLBACK_REFUSES' END,
              'no client_admin limitation snapshot and no client_admin final-release decision',
              'client_admin snapshots=' || coalesce(s.n::text, 'n/a') || '; client_admin decisions=' || coalesce(d.n::text, 'n/a'),
              'R04 raises "rollback refused: client_admin release decisions exist" and changes nothing. Never delete organization decisions to force it.'
         FROM (SELECT (CASE WHEN to_regclass('kai.limitation_snapshots') IS NULL THEN NULL
        ELSE (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM kai.limitation_snapshots WHERE confirmed_by_role = ''client_admin''', true, true, '')))[1]::text::bigint END) AS n) s,
              (SELECT (CASE WHEN to_regclass('kai.human_authority_decisions') IS NULL THEN NULL
        ELSE (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM kai.human_authority_decisions WHERE decided_by_role = ''client_admin''', true, true, '')))[1]::text::bigint END) AS n) d
  UNION ALL
  SELECT 102, 'RP', 'R03',
              CASE WHEN coalesce(e.n, 0) + coalesce(l.n, 0) + coalesce(m.n, 0) + coalesce(f.n, 0) = 0 THEN 'SAFE_TO_ROLL_BACK' ELSE 'UNSAFE_ROLLBACK_REFUSES' END,
              'no measurement evidence, record locator, measurement or measurement definition',
              'measurement evidence=' || coalesce(e.n::text, 'n/a') || '; record locators=' || coalesce(l.n::text, 'n/a')
                || '; evidence_measurements=' || coalesce(m.n::text, 'table absent') || '; source_measurement_definitions=' || coalesce(f.n::text, 'table absent'),
              'R03 refuses while measurement evidence or locators exist; it drops both P2-01M tables (definitions included) otherwise.'
         FROM (SELECT (CASE WHEN to_regclass('kai.evidence_items') IS NULL THEN NULL
        ELSE (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM kai.evidence_items WHERE evidence_type = ''source_record_count_measurement''', true, true, '')))[1]::text::bigint END) AS n) e,
              (SELECT (CASE WHEN to_regclass('kai.source_locators') IS NULL THEN NULL
        ELSE (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM kai.source_locators WHERE locator_type = ''source_data_records''', true, true, '')))[1]::text::bigint END) AS n) l,
              (SELECT (CASE WHEN to_regclass('kai.evidence_measurements') IS NULL THEN NULL
        ELSE (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM kai.evidence_measurements', true, true, '')))[1]::text::bigint END) AS n) m,
              (SELECT (CASE WHEN to_regclass('kai.source_measurement_definitions') IS NULL THEN NULL
        ELSE (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM kai.source_measurement_definitions', true, true, '')))[1]::text::bigint END) AS n) f
  UNION ALL
  SELECT 103, 'RP', 'R02',
              CASE WHEN coalesce(c.n, 0) = 0 THEN 'SAFE_TO_ROLL_BACK' ELSE 'UNSAFE_ROLLBACK_FAILS' END,
              'no client_admin sensitivity decision',
              'client_admin sensitivity decisions=' || coalesce(c.n::text, 'n/a'),
              'R02 has no guard: with client_admin decisions present its re-added CHECK fails validation, the transaction aborts and nothing changes (run ROLLBACK; in pgAdmin).'
         FROM (SELECT (CASE WHEN to_regclass('kai.intake_sensitivity_review_decisions') IS NULL THEN NULL
        ELSE (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM kai.intake_sensitivity_review_decisions WHERE decided_by_role = ''client_admin''', true, true, '')))[1]::text::bigint END) AS n) c
  UNION ALL
  SELECT 104, 'RP', 'R01',
              CASE WHEN a.n IS NULL THEN 'NOT_APPLIED' WHEN a.n = 0 THEN 'SAFE_TO_ROLL_BACK' ELSE 'DESTRUCTIVE_APP_ROLLBACK_FIRST' END,
              'no P1 downstream attempt rows, and the application already rolled back to a revision that does not use the table',
              'intake_p1_downstream_attempts rows=' || coalesce(a.n::text, 'table absent'),
              'R01 drops the table and its attempt budgets. Run it only after the application no longer references the table.'
         FROM (SELECT (CASE WHEN to_regclass('kai.intake_p1_downstream_attempts') IS NULL THEN NULL
        ELSE (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM kai.intake_p1_downstream_attempts', true, true, '')))[1]::text::bigint END) AS n) a
)
SELECT seq, section, check_id, status, expected, observed, detail FROM checks
UNION ALL
SELECT 999, 'OVERALL', 'OVERALL', 'INFO', 'see each R row', 'counts only', 'Roll back in reverse order, only what was applied, only when its row is SAFE_TO_ROLL_BACK.'
ORDER BY seq;
